post_content:
{#
  =============================================================================
  TEMPLATE-PART: Club-Logo (nur in anderen Views per include nutzen)
  Meta Box: {{ include('partial-club-team-logo') }} — Context wie Eltern-View
  Doku: https://docs.metabox.io/tutorials/create-reusable-template-parts
  =============================================================================
  VOR include setzen: team_post = Club-Post (z. B. home, away)
  Optional: logo_extra_class, logo_max_width, logo_max_height, logo_loading,
            logo_decoding, logo_fetchpriority
  =============================================================================
#}
{% set thumb = null %}
{% if team_post is defined and team_post.thumbnail is defined %}
  {% if team_post.thumbnail.medium_large is defined and team_post.thumbnail.medium_large.url %}
    {% set thumb = team_post.thumbnail.medium_large %}
  {% elseif team_post.thumbnail.medium is defined and team_post.thumbnail.medium.url %}
    {% set thumb = team_post.thumbnail.medium %}
  {% endif %}
{% endif %}
{% if thumb and thumb.url %}
<img class="club-team-logo{{ logo_extra_class is defined and logo_extra_class ? ' ' ~ logo_extra_class : '' }}" src="{{ thumb.url }}" alt="{{ thumb.alt|default('') }}" title="{{ team_post.title|default('') }}"{% if logo_max_width is defined and logo_max_width %} width="{{ logo_max_width }}"{% endif %}{% if logo_max_height is defined and logo_max_height %} height="{{ logo_max_height }}"{% endif %} loading="{{ logo_loading|default('lazy') }}" decoding="{{ logo_decoding|default('async') }}"{% if logo_fetchpriority is defined and logo_fetchpriority %} fetchpriority="{{ logo_fetchpriority }}"{% endif %}>
{% endif %}
